namespace Garbati.OpsApi.Clients.Contracts.StaffIdentity;

// ActingStaffId is the currently logged-in Administrator's own StaffId (from the session, DESIGN.md
// Section 2.2) - OpsApi fills this in itself from the authenticated session, never accepts it from the
// browser (the browser cannot be trusted to say who it is; the session cookie already answers that).
// IdempotencyKey is likewise generated by OpsApi, not accepted from the browser, since the browser has no
// natural idempotency-key concept of its own for this action.
public record CreateStaffRequest(
    string IdempotencyKey,
    string ActingStaffId,
    string FullName,
    string Username,
    string Role);
